#include <vector>
#include <unordered_map>
#include <algorithm>

using namespace std;

class Solution {
public:
    vector<int> solveQueries(vector<int>& nums, vector<int>& queries) {
        int n = nums.size();
        vector<int> minDist(n, n);
        unordered_map<int, int> lastSeen;

        for (int i = 0; i < 2 * n; ++i) {
            int idx = i % n;
            int val = nums[idx];
            if (lastSeen.count(val)) {
                int prevIdx = lastSeen[val] % n;
                int d = i - lastSeen[val];
                minDist[idx] = min(minDist[idx], d);
                minDist[prevIdx] = min(minDist[prevIdx], d);
            }
            lastSeen[val] = i;
        }

        vector<int> ans;
        ans.reserve(queries.size());
        for (int q : queries) {
            ans.push_back(minDist[q] < n ? minDist[q] : -1);
        }
        return ans;
    }
};

import java.util.*;

class Solution {
    public int[] solveQueries(int[] nums, int[] queries) {
        int n = nums.length;
        int[] minDist = new int[n];
        Arrays.fill(minDist, n);
        Map<Integer, Integer> lastSeen = new HashMap<>();

        for (int i = 0; i < 2 * n; i++) {
            int idx = i % n;
            int val = nums[idx];
            if (lastSeen.containsKey(val)) {
                int prevIdx = lastSeen.get(val) % n;
                int d = i - lastSeen.get(val);
                minDist[idx] = Math.min(minDist[idx], d);
                minDist[prevIdx] = Math.min(minDist[prevIdx], d);
            }
            lastSeen.put(val, i);
        }

        int[] ans = new int[queries.length];
        for (int i = 0; i < queries.length; i++) {
            int q = queries[i];
            ans[i] = minDist[q] < n ? minDist[q] : -1;
        }
        return ans;
    }
}

var solveQueries = function(nums, queries) {
    const n = nums.length;
    const minDist = new Array(n).fill(n);
    const lastSeen = new Map();

    for (let i = 0; i < 2 * n; i++) {
        const idx = i % n;
        const val = nums[idx];
        if (lastSeen.has(val)) {
            const prevIdx = lastSeen.get(val) % n;
            const d = i - lastSeen.get(val);
            if (d < minDist[idx]) minDist[idx] = d;
            if (d < minDist[prevIdx]) minDist[prevIdx] = d;
        }
        lastSeen.set(val, i);
    }

    const ans = new Array(queries.length);
    for (let i = 0; i < queries.length; i++) {
        const q = queries[i];
        ans[i] = minDist[q] < n ? minDist[q] : -1;
    }
    return ans;
};
